class Solution {
  public int generateKey(int num1, int num2, int num3) {
    int answer = 0, place = 1;
    for (int i = 0; i < 4; i++) {
      answer += Math.min(num1 % 10, Math.min(num2 % 10, num3 % 10)) * place;
      num1 /= 10;
      num2 /= 10;
      num3 /= 10;
      place *= 10;
    }
    return answer;
  }
}
